    seg=SEG[k]; i0,d0=PH[k]; per=2*(len(seg)-1); s=(i0+d0*t)%per
    return seg[s if s<len(seg) else per-s]
def ofac(k,t): return ophase(k,t+1)
REDFR={(5,3):(5,4),(6,3):(5,3)}
def chase(c,p,D=D):
    d=D[p]; best=None
    for v in sorted(ADJ[c]):
        if d[v]>=d[c]: continue
        dr=abs(v[0]-p[0])-abs(c[0]-p[0]); dc=abs(v[1]-p[1])-abs(c[1]-p[1])
        if best is None or (dr,dc)<best[0]: best=((dr,dc),v)
    return best[1] if best else c
Dm={'UP':(-1,0),'DOWN':(1,0),'LEFT':(0,-1),'RIGHT':(0,1)}
GOAL=(5,4)
def search(p0,c0,t0,maxt=40):
    start=(p0,c0,t0,0,0); seen={start}; par={}; q=collections.deque([start]); found=None
    while q:
        st=q.popleft(); p,c,t,om,rd=st
        if p==GOAL: found=st; break
        if t>=maxt: continue
        c1=chase(c,p)
        if c1==p: continue
        for mv,d in Dm.items():
            n=(p[0]+d[0],p[1]+d[1])
            if n not in ADJ[p]: continue
            if n==c1: continue
            ok=True; rdm=rd; om_=om
            for idx,rr in enumerate([(5,3),(6,3)]):
                if not (rdm>>idx)&1:
                    if n==REDFR[rr]: ok=False
            if not ok: continue
            for idx,rr in enumerate([(5,3),(6,3)]):
                if not (rdm>>idx)&1 and n==rr:
                    if p==REDFR[rr]: ok=False
                    else: rdm |= (1<<idx)
            if not ok: continue
            for k in range(3):
                if (om_>>k)&1: continue
                op_now=ophase(k,t); op_next=ophase(k,t+1)
                if op_next==n: ok=False; break
                if op_next==p and op_now!=n: pass
                if n==op_now:
                    if p==ofac(k,t): ok=False; break
                    else: om_ |= (1<<k)
            if not ok: continue
            ns=(n,c1,t+1,om_,rdm)
            if ns not in seen: seen.add(ns); par[ns]=(st,mv); q.append(ns)
    if not found: return None
    seq=[]; s=found
    while s!=start: s,mv=par[s]; seq.append(mv)
    seq.reverse(); return seq,len(found),len(seen)
