    blk=[[a[r0+3*i+1][c0+3*j+1] for j in range(nb_c)] for i in range(nb_r)]
    nr=(nb_r+1)//2; nc=(nb_c+1)//2
    rooms=[[blk[2*i][2*j] for j in range(nc)] for i in range(nr)]
    hset=set(); vset=set()
