def rinfo(fr):
    a=fr.ascii.split('\n')
    pts=[(i,j) for i in range(60) for j in range(64) if a[i][j]=='r']
    if not pts: return None
    r0=min(p[0] for p in pts); c0=min(p[1] for p in pts)
    room=((r0-14)//6,(c0-14)//6)
    # eye: pixel of color p or Y within block 3x3
    eye=None
    for i in range(r0,r0+3):
        for j in range(c0,c0+3):
            if a[i][j] in 'pY': eye=(a[i][j],i-r0-1,j-c0-1)
    return (room,eye,len(pts))

