            if not(abs(cell[0]-x[0])<=2 and abs(cell[1]-x[1])<=2): return ('precheck',a,'not in disc bbox',pos,pl,log)
            for p in pos:
                if abs(cell[0]-p[0])<=2 and abs(cell[1]-p[1])<=2: return ('precheck',a,'in diamond bbox '+str(p),pos,pl,log)
        else:
            i=a[1]; cell=a[2]
            if cur[cell[0]][cell[1]]!='B': return ('precheck',a,'ring busy '+cur[cell[0]][cell[1]],pos,pl,log)
        res=action([{'action':'MOUSE','row':cell[0],'col':cell[1]}])
        npos=list(pos); npl=pl
        if kind=='des': npl=a[1]
        elif kind=='cell': npos[pl]=a[2]
