        if not(okM and okD): return ('verify_fail',log[-1],npos,npl,log)
        if res.get('level_completed') or res.get('run_complete'): return ('END:'+str({k:v for k,v in res.items() if k in ('level_completed','run_complete','state')}),log,npos,npl,log)
        pos,pl,f=npos,npl,f2
